create table if not exists public.agent_approvals(id uuid primary key default gen_random_uuid(),approved boolean not null default false,created_at timestamptz not null default now());alter table public.agent_approvals enable row level security;create or replace function public.agent_can_write(p_id uuid) returns boolean language sql security definer set search_path=public as $$ select approved from public.agent_approvals where id=p_id $$;